contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, address spender, uint256 amount) public {
        require(recipient != address(0));

        // A zero-supply token cannot transfer: balance check fails, state unchanged.
        bool transferReverted;
        try c.transfer(recipient, amount) { transferReverted = false; } catch { transferReverted = true; }

        // Same for burn: nothing to burn, so it must revert.
        bool burnReverted;
        try c.burn(amount) { burnReverted = false; } catch { burnReverted = true; }

        // approve reverts iff the spender is the zero address.
        bool approveReverted;
        try c.approve(spender, amount) { approveReverted = false; } catch { approveReverted = true; }

        assert(
            transferReverted
            && burnReverted
            && c.balanceOf(address(this)) == 0
            && c.balanceOf(recipient) == 0
            && c.totalSupply() == 0
            && c.allowance(address(this), recipient) == 0
            && approveReverted == (spender == address(0))
            && c.allowance(address(this), spender) == 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mintAmount, uint256 burnAmount) public {
        require(mintAmount > 0);
        require(burnAmount > 0);

        // Setup: c mints mintAmount to this test contract. _mint is internal,
        // but the test contract is the deployer/msg.sender; minting is not
        // exposed, so instead use approve/transfer to build a balance we control.
        // Since c has no public mint, mint via constructor-less path: we instead
        // test the general burn rule using whatever balance we have, driven by
        // an untrusted external path. To guarantee a nonzero balance we rely on
        // transferFrom with max approval semantics is not possible either.
        // Therefore we express the rule conditionally on reachability via try/catch.

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        if (burnAmount <= balBefore) {
            c.burn(burnAmount);
            reverted = false;
        } else {
            try c.burn(burnAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        if (balBefore >= burnAmount) {
            assert(!reverted && balBefore - balAfter == burnAmount && supplyBefore - supplyAfter == burnAmount);
        } else {
            assert(reverted && balAfter == balBefore && supplyAfter == supplyBefore);
        }
    }

    receive() external payable {}
}

