contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));

        c.approve(address(this), type(uint256).max);
        c.transfer(address(this), amount);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        bool ok;
        if (amount > balBefore) {
            try c.transfer(recipient, amount) returns (bool r) { reverted = false; ok = r; }
            catch { reverted = true; }
        } else {
            ok = c.transfer(recipient, amount);
            reverted = false;
        }

        if (reverted) {
            assert(c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore && c.balanceOf(recipient) == 0);
        } else {
            assert(ok && c.balanceOf(address(this)) == balBefore - amount && c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

