contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address recipient, uint256 approveAmount, uint256 transferAmount) public {
        require(approveAmount > 0 && transferAmount > 0 && transferAmount <= approveAmount);
        require(spender != address(0) && recipient != address(0));
        address sender = address(this);

        c.approve(spender, approveAmount);

        bool ok;
        // top-level call via try is not allowed for state-changing calls, so just call directly
        // sender is this test contract, which holds no balance; mint balance first via transfer? not possible.
        // Instead test allowance semantics with recipient == sender so balance requirement still applies.
        // We need balance: use recipient==sender and give c tokens? Not possible without mint.
        // So assert the returned allowance delta path when transferAmount is covered by allowance but balance fails -> revert.
        // Simpler observable rule: allowance after approve equals approveAmount.
        uint256 beforeAllowance = c.allowance(sender, spender);

        // attempt transferFrom; expected to revert due to insufficient balance (sender balance 0)
        bool reverted;
        try c.transferFrom(sender, recipient, transferAmount) returns (bool r) {
            ok = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterAllowance = c.allowance(sender, spender);
        uint256 balance = c.balanceOf(sender);

        assert(beforeAllowance == approveAmount
            && afterAllowance == approveAmount
            && balance == 0
            && (reverted || (ok && c.balanceOf(recipient) == transferAmount && c.allowance(sender, spender) == approveAmount - transferAmount)));
    }
    receive() external payable {}
}

