        }
        uint256 allowanceAfterExcess = c.allowance(address(this), spender);

        assert(
            !validReverted &&
            allowanceAfterIncrease == addedValue &&
            allowanceAfterDecrease == addedValue - subtractedValue &&
            excessReverted &&
            allowanceAfterExcess == allowanceAfterDecrease
        );
    }
}

