        bool ok3 = c.decreaseAllowance(spender, delta);
        uint256 fin = c.allowance(address(this), spender);

        assert(ok1 && ok2 && ok3 && before == initial && mid == initial + delta && fin == initial);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 initial, uint256 sub) public {
        require(spender != address(0));
        require(sub > 0);

        bool ok = c.approve(spender, initial);
        uint256 afterApprove = c.allowance(address(this), spender);

        bool reverted;
        try c.decreaseAllowance(spender, sub) { reverted = false; }
        catch { reverted = true; }

        uint256 fin = c.allowance(address(this), spender);

        assert(
            ok &&
            afterApprove == initial &&
            ((reverted && fin == initial) ||
             (!reverted && sub <= initial && fin == initial - sub))
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount > 0);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(amount) { reverted = false; }
        catch { reverted = true; }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        assert(
            (reverted && amount > balBefore && supplyAfter == supplyBefore && balAfter == balBefore) ||
            (!reverted && amount <= balBefore && supplyAfter + amount == supplyBefore && balAfter + amount == balBefore)
        );
    }

    receive() external payable {}
}

